 function drawObject(g,o){g.save();if(o.type==='rect'){g.strokeStyle=o.color;g.lineWidth=o.lineWidth;g.strokeRect(o.x,o.y,o.w,o.h);}else if(o.type==='arrow')drawArrow(g,o);else if(o.type==='text'){g.font=`700 ${o.fontSize}px sans-serif`;g.textBaseline='alphabetic';g.fillStyle=o.color;g.shadowColor='rgba(255,255,255,.85)';g.shadowBlur=Math.max(2,o.fontSize/12);g.fillText(o.text,o.x,o.y);}else if(o.type==='number'){g.fillStyle=o.color;g.beginPath();g.arc(o.x,o.y,o.size*.62,0,Math.PI*2);g.fill();g.fillStyle='#fff';g.font=`700 ${o.size}px sans-serif`;g.textAlign='center';g.textBaseline='middle';g.fillText(String(o.number),o.x,o.y+1);}else if(o.type==='mosaic')drawMosaic(g,o);g.restore();}
