addTool('image-redact','image','🔒','圖片敏感資訊遮蔽工具','實心遮罩可選取、移動、縮放與刪除；支援畫面縮放，輸出時才真正壓平到 PNG。','圖片 遮蔽 隱私 redact 黑框 移動 縮放 放大',()=>{
 mount.innerHTML=panel('圖片遮蔽',`${fileDrop('irFile','選擇圖片','image/*',false)}<div class="success-box">實心遮罩會在「下載輸出」時真正覆寫輸出圖片像素。遮罩在編輯中仍可移動、縮放或刪除；最後輸出 PNG 才會永久壓平。</div>
 <div class="annotation-toolbar"><div class="tool-tabs redact-modes"><button data-rmode="select" class="active">↖ 選取／移動</button><button data-rmode="add">⬛ 新增遮罩</button></div><div class="zoom-toolbar compact"><button class="ghost-btn" id="irZoomOut">−</button><button class="ghost-btn" id="irFit">適合畫面</button><button class="ghost-btn" id="irActual">100%</button><button class="ghost-btn" id="irZoomIn">＋</button><span id="irZoomLabel">100%</span></div></div>
 <p class="hint">新增遮罩後會自動回到選取模式。拖曳遮罩本體可移動，拖曳四角可縮放；Delete 可刪除，方向鍵可微調。縮放只影響檢視，不影響原始輸出解析度。</p>
 <div class="canvas-wrap annotation-stage mt-12" id="irStage"><canvas id="irCanvas" width="900" height="560" tabindex="0" aria-label="敏感資訊遮蔽畫布"></canvas></div><div class="annotation-status" id="irStatus">尚未載入圖片</div><div class="actions"><button class="ghost-btn" id="irUndo">↶ 復原</button><button class="ghost-btn" id="irRedo">↷ 重做</button><button class="danger-btn" id="irDelete">刪除選取遮罩</button><button class="danger-btn" id="irClear">清除全部遮罩</button><button class="primary-btn" id="irSave">下載已遮蔽圖片</button></div>`);
 const c=$('#irCanvas'),stage=$('#irStage'),ctx=c.getContext('2d',{alpha:false}),base=document.createElement('canvas'),bctx=base.getContext('2d',{alpha:false});
 const MAX_MASKS=500,HISTORY_MAX=50;let masks=[],history=[[]],redoStack=[],selected=-1,mode='select',drag=null,draft=null,hasImage=false,zoom=1;
 const clone=v=>JSON.parse(JSON.stringify(v));
 function setZoom(v){zoom=clamp(v,.1,3);c.dataset.zoom=String(Math.round(zoom*100));c.className=`zoom-canvas zoom-${Math.round(zoom*100)}`;$('#irZoomLabel').textContent=`${Math.round(zoom*100)}%`;render();}
 function fitZoom(){const availW=Math.max(120,stage.clientWidth-24),availH=Math.max(180,window.innerHeight*.62);return clamp(Math.min(1,availW/Math.max(1,c.width),availH/Math.max(1,c.height)),.1,3);}
 function norm(r){if(r.w<0){r.x+=r.w;r.w=-r.w;}if(r.h<0){r.y+=r.h;r.h=-r.h;}return r;}
 function clampMask(r){r.w=clamp(r.w,3,c.width);r.h=clamp(r.h,3,c.height);r.x=clamp(r.x,0,Math.max(0,c.width-r.w));r.y=clamp(r.y,0,Math.max(0,c.height-r.h));return r;}
 function drawMask(g,r){g.fillStyle='#111827';g.fillRect(r.x,r.y,r.w,r.h);}
 function handles(r){return[{id:'nw',x:r.x,y:r.y},{id:'ne',x:r.x+r.w,y:r.y},{id:'sw',x:r.x,y:r.y+r.h},{id:'se',x:r.x+r.w,y:r.y+r.h}];}
 function drawSelection(r){const hs=clamp(10/zoom,5,40),pad=clamp(4/zoom,2,16);ctx.save();ctx.strokeStyle='#2563eb';ctx.lineWidth=clamp(2/zoom,1,6);ctx.setLineDash([clamp(8/zoom,4,28),clamp(6/zoom,3,20)]);ctx.strokeRect(r.x-pad,r.y-pad,r.w+pad*2,r.h+pad*2);ctx.setLineDash([]);for(const h of handles(r)){ctx.fillStyle='#fff';ctx.strokeStyle='#2563eb';ctx.fillRect(h.x-hs,h.y-hs,hs*2,hs*2);ctx.strokeRect(h.x-hs,h.y-hs,hs*2,hs*2);}ctx.restore();}
 function render(clean=false){ctx.clearRect(0,0,c.width,c.height);if(hasImage)ctx.drawImage(base,0,0);else{ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#94a3b8';ctx.font='24px sans-serif';ctx.textAlign='center';ctx.fillText('請先匯入圖片',c.width/2,c.height/2);}masks.forEach(r=>drawMask(ctx,r));if(draft){ctx.save();ctx.globalAlpha=.72;drawMask(ctx,norm({...draft}));ctx.restore();}if(!clean&&selected>=0&&masks[selected])drawSelection(masks[selected]);$('#irUndo').disabled=history.length<=1;$('#irRedo').disabled=!redoStack.length;$('#irDelete').disabled=selected<0;$('#irClear').disabled=!masks.length;$('#irStatus').textContent=hasImage?`原圖 ${c.width}×${c.height}｜${masks.length} 個遮罩｜檢視 ${Math.round(zoom*100)}%${selected>=0?`｜已選第 ${selected+1} 個`:''}`:'尚未載入圖片';}
 function commit(){history.push(clone(masks));if(history.length>HISTORY_MAX)history.shift();redoStack=[];render();}
 function apply(st){masks=clone(st);selected=Math.min(selected,masks.length-1);render();}
 function undo(){if(history.length<=1)return;redoStack.push(history.pop());apply(history[history.length-1]);}
 function redo(){if(!redoStack.length)return;const st=redoStack.pop();history.push(clone(st));apply(st);}
 async function load(f){try{if(!f||!validateFiles([f],LIMITS.image))return;const b=await createImageBitmap(f);if(b.width*b.height>20000000||b.width>12000||b.height>12000){b.close?.();return toast('圖片尺寸過大：遮蔽工具上限 2,000 萬像素，且單邊不得超過 12,000px');}base.width=c.width=b.width;base.height=c.height=b.height;bctx.clearRect(0,0,base.width,base.height);bctx.drawImage(b,0,0);b.close?.();masks=[];history=[[]];redoStack=[];selected=-1;drag=null;draft=null;hasImage=true;requestAnimationFrame(()=>setZoom(fitZoom()));c.focus();}catch(e){console.error(e);toast(`圖片載入失敗：${e.message||'不支援的圖片格式'}`);}}
 $('#irFile').onchange=e=>e.target.files[0]&&load(e.target.files[0]);
 function setMode(v){mode=v;draft=null;drag=null;$$('.redact-modes [data-rmode]').forEach(b=>b.classList.toggle('active',b.dataset.rmode===mode));c.classList.toggle('cursor-crosshair',mode==='add');render();}
 $$('.redact-modes [data-rmode]').forEach(b=>b.onclick=()=>setMode(b.dataset.rmode));
 $('#irZoomOut').onclick=()=>setZoom(zoom/1.25);$('#irZoomIn').onclick=()=>setZoom(zoom*1.25);$('#irActual').onclick=()=>setZoom(1);$('#irFit').onclick=()=>setZoom(fitZoom());
 function pos(e){const r=c.getBoundingClientRect();return{x:(e.clientX-r.left)*c.width/r.width,y:(e.clientY-r.top)*c.height/r.height};}
 function hitMask(p){const tol=clamp(8/zoom,3,40);for(let i=masks.length-1;i>=0;i--){const r=masks[i];if(p.x>=r.x-tol&&p.x<=r.x+r.w+tol&&p.y>=r.y-tol&&p.y<=r.y+r.h+tol)return i;}return-1;}
 function hitHandle(p,r){const tol=clamp(18/zoom,8,70);for(const h of handles(r))if(Math.abs(p.x-h.x)<=tol&&Math.abs(p.y-h.y)<=tol)return h.id;return null;}
 function resize(r,handle,p){const opp={nw:{x:r.x+r.w,y:r.y+r.h},ne:{x:r.x,y:r.y+r.h},sw:{x:r.x+r.w,y:r.y},se:{x:r.x,y:r.y}}[handle];if(!opp)return;const x=clamp(p.x,0,c.width),y=clamp(p.y,0,c.height);r.x=Math.min(opp.x,x);r.y=Math.min(opp.y,y);r.w=Math.max(3,Math.abs(x-opp.x));r.h=Math.max(3,Math.abs(y-opp.y));clampMask(r);}
 c.onpointerdown=e=>{if(!hasImage)return toast('請先載入圖片');const p=pos(e);c.focus();try{c.setPointerCapture?.(e.pointerId);}catch{}if(mode==='add'){draft={x:p.x,y:p.y,w:0,h:0};drag={kind:'draw',start:p,last:p};render();return;}if(selected>=0&&masks[selected]){const h=hitHandle(p,masks[selected]);if(h){drag={kind:'resize',handle:h,last:p};return;}}const i=hitMask(p);selected=i;drag=i>=0?{kind:'move',last:p}:null;render();};
 c.onpointermove=e=>{if(!drag)return;const p=pos(e);if(drag.kind==='draw'&&draft){draft.w=p.x-drag.start.x;draft.h=p.y-drag.start.y;render();return;}if(selected<0||!masks[selected])return;if(drag.kind==='move'){const r=masks[selected],dx=p.x-drag.last.x,dy=p.y-drag.last.y;r.x+=dx;r.y+=dy;clampMask(r);drag.last=p;render();}else if(drag.kind==='resize'){resize(masks[selected],drag.handle,p);drag.last=p;render();}};
 c.onpointerup=()=>{if(!drag)return;if(drag.kind==='draw'&&draft){const r=clampMask(norm(draft));draft=null;drag=null;if(r.w>3&&r.h>3){if(masks.length>=MAX_MASKS)return toast(`單張圖片最多 ${MAX_MASKS} 個遮罩`);masks.push(r);selected=masks.length-1;commit();}setMode('select');return;}if(drag.kind==='move'||drag.kind==='resize')commit();drag=null;render();};
 c.onpointercancel=()=>{draft=null;drag=null;render();};
 function del(){if(selected<0)return;masks.splice(selected,1);selected=Math.min(selected,masks.length-1);commit();}
 $('#irUndo').onclick=undo;$('#irRedo').onclick=redo;$('#irDelete').onclick=del;$('#irClear').onclick=()=>{if(!masks.length)return;if(confirm('確定清除全部遮罩？')){masks=[];selected=-1;commit();}};
 function key(e){if(state.currentTool!=='image-redact')return;const tag=e.target?.tagName;if(tag==='INPUT'||tag==='TEXTAREA'||tag==='SELECT')return;const ctrl=e.ctrlKey||e.metaKey;if(ctrl&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return;}if(ctrl&&e.key.toLowerCase()==='y'){e.preventDefault();redo();return;}if(ctrl&&(e.key==='+'||e.key==='=')){e.preventDefault();setZoom(zoom*1.25);return;}if(ctrl&&e.key==='-'){e.preventDefault();setZoom(zoom/1.25);return;}if((e.key==='Delete'||e.key==='Backspace')&&selected>=0){e.preventDefault();del();return;}if(selected>=0&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const step=e.shiftKey?10:1,r=masks[selected];r.x+=e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0;r.y+=e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0;clampMask(r);commit();}}
 function releaseRedactMemory(){masks=[];history=[[]];redoStack=[];draft=null;drag=null;selected=-1;hasImage=false;base.width=base.height=1;c.width=c.height=1;}document.addEventListener('keydown',key);setToolCleanup(()=>{document.removeEventListener('keydown',key);c.onpointerdown=c.onpointermove=c.onpointerup=c.onpointercancel=null;releaseRedactMemory();});
 $('#irSave').onclick=()=>{if(!hasImage)return toast('請先載入圖片');const out=document.createElement('canvas'),g=out.getContext('2d',{alpha:false});out.width=base.width;out.height=base.height;g.drawImage(base,0,0);masks.forEach(r=>drawMask(g,r));out.toBlob(b=>{if(b)saveBlob(b,'敏感資訊已遮蔽.png',`原始解析度 ${base.width}×${base.height}；${masks.length} 個實心遮罩已壓平。`);else toast('無法輸出圖片');out.width=out.height=1;},'image/png');};setZoom(1);
});

addTool('qr-batch','list','🔗','QR Code 批次產生器','批次產生 QR，採分批渲染避免頁面長時間凍結，支援進度、取消與 ZIP 下載。','qr code 批次 網址 名單 zip 容錯 尺寸 進度 取消',()=>{
 if(!requireLib('OfficeQR',window.OfficeQR)||!requireLib('JSZip',window.JSZip))return;
 mount.innerHTML=panel('QR Code 批次產生',`${textAreaField('qrIn','內容（一行一筆）','https://example.com\n王小明')}<div class="row"><div class="field"><label>圖片尺寸</label><select id="qrSize"><option value="180">180×180</option><option value="256" selected>256×256</option><option value="384">384×384</option><option value="512">512×512</option></select></div><div class="field"><label>容錯等級</label><select id="qrLevel"><option value="L">L</option><option value="M" selected>M</option><option value="Q">Q</option><option value="H">H</option></select></div></div><div class="hint">單次最多 200 筆；每筆最多 1,500 bytes。V1.7 會分批產生並把控制權交還瀏覽器，避免大量 QR 時整頁看起來當機。</div><div class="actions"><button class="primary-btn" id="qrRun">產生 QR Code</button><button class="danger-btn" id="qrCancel" disabled>取消處理</button><button class="ghost-btn" id="qrZip" disabled>全部下載 ZIP</button></div><div class="progress-wrap hidden" id="qrProgressWrap"><progress id="qrProgress" max="100" value="0"></progress><span id="qrProgressText">0%</span></div><div id="qrMeta"></div><div id="qrOut" class="qr-grid"></div>`);
 let items=[],jobToken=0,busy=false;
 function releaseItems(){for(const x of items){try{x.canvas.width=x.canvas.height=1;}catch{}}items=[];}
 function setBusy(v){busy=v;$('#qrRun').disabled=v;$('#qrCancel').disabled=!v;$('#qrIn').disabled=v;$('#qrSize').disabled=v;$('#qrLevel').disabled=v;}
 function progress(done,total){const pct=total?Math.round(done/total*100):0;$('#qrProgress').value=pct;$('#qrProgressText').textContent=`${done}/${total}（${pct}%）`;$('#qrProgressWrap').classList.remove('hidden');}
 $('#qrRun').onclick=async()=>{if(busy)return;const source=$('#qrIn').value;if(!validateTextSize(source,1_000_000,'QR 內容'))return;const lines=parseLines(source);if(!lines.length)return toast('請先輸入內容');if(lines.length>200)return toast('單次最多 200 筆 QR Code');const token=++jobToken,out=$('#qrOut'),size=+$('#qrSize').value||256,level=$('#qrLevel').value;releaseItems();out.innerHTML='';let fail=0,cancelled=false;setBusy(true);$('#qrZip').disabled=true;progress(0,lines.length);
  for(let i=0;i<lines.length;i++){
   if(token!==jobToken){cancelled=true;break;}const t=lines[i];
   try{if(new TextEncoder().encode(t).length>1500)throw new Error('內容過長');const card=document.createElement('div'),box=document.createElement('div'),hint=document.createElement('div'),btn=document.createElement('button');card.className='qr-card';box.className='qr-box';hint.className='hint';hint.textContent=t;btn.className='ghost-btn';btn.classList.add('mt-8');btn.textContent='下載';const canvas=OfficeQR.renderCanvas(t,size,level);box.appendChild(canvas);card.append(box,hint,btn);out.appendChild(card);const name=`QR_${String(i+1).padStart(3,'0')}.png`;items.push({canvas,name,text:t});btn.onclick=()=>canvas.toBlob(b=>b&&saveBlob(b,name,`QR 內容：${t.slice(0,120)}`),'image/png');}
   catch(e){fail++;const err=document.createElement('div');err.className='error-box';err.textContent=`第 ${i+1} 筆無法產生：${e.message}`;out.appendChild(err);}
   progress(i+1,lines.length);if(i%10===9)await new Promise(r=>requestAnimationFrame(r));
  }
  setBusy(false);$('#qrZip').disabled=!items.length;$('#qrMeta').innerHTML=`<div class="metric-grid"><div class="metric"><b>${items.length}</b><span>成功</span></div><div class="metric"><b>${fail}</b><span>失敗</span></div><div class="metric"><b>${cancelled?'是':'否'}</b><span>使用者取消</span></div></div>${cancelled?'<div class="warn-box">處理已取消；目前已完成的 QR 仍可下載。</div>':''}`;
 };
 $('#qrCancel').onclick=()=>{if(!busy)return;++jobToken;toast('已要求取消 QR 批次處理');};
 $('#qrZip').onclick=async()=>{if(!items.length)return toast('請先產生 QR Code');const zip=new JSZip(),map=[['檔名','內容']];let i=0;for(const x of items){const blob=await new Promise(r=>x.canvas.toBlob(r,'image/png'));if(blob){zip.file(x.name,blob);map.push([x.name,x.text]);}i++;if(i%20===0)await new Promise(r=>requestAnimationFrame(r));}zip.file('QR對照.csv','\ufeff'+map.map(r=>r.map(csvEscape).join(',')).join('\r\n'));saveBlob(await zip.generateAsync({type:'blob'}),'QR_Code_批次結果.zip',`共 ${items.length} 張 QR Code。`);};
 setToolCleanup(()=>{++jobToken;releaseItems();});
},true);

addTool('random-group','list','🔀','名單隨機分組器','平均分組並主動提示重複資料；預設保留每一筆，不再默默刪除同名資料。','名單 分組 隨機 group csv 重複 保留',()=>{
 mount.innerHTML=panel('隨機分組',`${textAreaField('rgIn','名單（一行一人）','王小明\n陳小華\n林小美')}<div class="row">${inputField('rgCount','組數','number','3','min="2" max="50"')}<label><input id="rgDedupe" type="checkbox"> 移除完全重複姓名</label></div><div class="hint">V1.7 預設保留每一筆名單，避免兩位同名人員被誤刪；若確定重複資料是重複輸入，再勾選移除。</div><div class="actions"><button class="primary-btn" id="rgRun">開始分組</button><button class="ghost-btn" id="rgCopy" disabled>複製結果</button><button class="ghost-btn" id="rgCsv" disabled>下載 CSV</button></div><div id="rgOut"></div>`);let groups=[];function run(){const src=$('#rgIn').value;if(!validateTextSize(src,1_000_000,'名單'))return;const raw=parseLines(src);if(raw.length>20000)return toast('名單過多，上限 20,000 人');const duplicateCount=raw.length-unique(raw).length,removeDup=$('#rgDedupe').checked,names=shuffle(removeDup?unique(raw):raw),n=clamp(+$('#rgCount').value||2,2,50);if(!names.length)return toast('請輸入名單');if(n>names.length)toast('組數大於人數，部分組別會是空的');groups=Array.from({length:n},()=>[]);names.forEach((x,i)=>groups[i%n].push(x));$('#rgCopy').disabled=$('#rgCsv').disabled=false;$('#rgOut').innerHTML=`${duplicateCount?`<div class="warn-box">偵測到 ${duplicateCount} 筆完全相同姓名；本次${removeDup?'已移除':'全部保留'}。</div>`:''}`+groups.map((g,i)=>`<div class="panel"><h3>第 ${i+1} 組（${g.length} 人）</h3>${g.map((x,j)=>`${j+1}. ${esc(x)}`).join('<br>')||'<span class="hint">空組</span>'}</div>`).join('');}$('#rgRun').onclick=run;$('#rgCopy').onclick=()=>copyText(groups.map((g,i)=>`第 ${i+1} 組\n${g.join('\n')}`).join('\n\n'));$('#rgCsv').onclick=()=>downloadCsvRows([['組別','序號','姓名'],...groups.flatMap((g,i)=>g.map((x,j)=>[`第${i+1}組`,j+1,x]))],'隨機分組結果.csv');
},true);

addTool('raffle','list','🎲','抽籤／抽獎工具','安全亂數先決定結果，再播放動畫；支援正取、候補、全螢幕與完整時間紀錄。','抽籤 抽獎 random 名單 動畫 紀錄 正取 候補 全螢幕',()=>{
 mount.innerHTML=panel('抽籤／抽獎',`${textAreaField('rfIn','名單（一行一人）')}<div class="row">${inputField('rfCount','正取人數','number','1','min="0" max="100"')}${inputField('rfAltCount','候補人數','number','0','min="0" max="100"')}<div class="field"><label>動畫</label><select id="rfAnimation"><option value="1200" selected>一般（約 1.2 秒）</option><option value="650">快速</option><option value="2000">戲劇效果</option><option value="0">關閉動畫</option></select></div><label><input id="rfDedupe" type="checkbox"> 移除完全重複姓名</label></div><div class="success-box">公平性設計：按下抽籤時先使用瀏覽器安全亂數確定正取與候補，動畫只負責呈現。V1.7 預設保留同名資料，避免誤刪不同的人。</div><div class="actions"><button class="primary-btn" id="rfRun">🎲 開始抽籤</button><button class="ghost-btn" id="rfFullscreen">⛶ 全螢幕結果</button><button class="ghost-btn" id="rfReset">重設本輪</button><button class="ghost-btn" id="rfCsv" disabled>下載紀錄 CSV</button></div><div id="rfOut" class="raffle-stage" aria-live="polite"><div class="raffle-placeholder">等待抽籤</div></div><div id="rfMeta"></div><div id="rfHistory"></div>`);
 let pool=[],drawn=[],source='',timer=null,token=0,busy=false,duplicateCount=0;
 function setBusy(v){busy=v;['rfRun','rfReset','rfIn','rfCount','rfAltCount','rfAnimation','rfDedupe'].forEach(id=>$('#'+id).disabled=v);}
 function reset(){token++;if(timer){clearInterval(timer);timer=null;}setBusy(false);source=$('#rfIn').value;if(!validateTextSize(source,1_000_000,'名單'))return false;const lines=parseLines(source);if(lines.length>20000){toast('名單過多，上限 20,000 人');return false;}duplicateCount=lines.length-unique(lines).length;const removeDup=$('#rfDedupe').checked,cleaned=removeDup?unique(lines):lines;pool=shuffle(cleaned);drawn=[];$('#rfOut').innerHTML='<div class="raffle-placeholder">等待抽籤</div>';$('#rfHistory').innerHTML='';$('#rfCsv').disabled=true;$('#rfMeta').innerHTML=`<div class="hint">有效名單 ${pool.length} 人${duplicateCount?`｜發現 ${duplicateCount} 筆完全相同姓名，本輪${removeDup?'已移除':'全部保留'}`:''}</div>`;return true;}
 function finish(winners,round,myToken){if(myToken!==token)return;if(timer){clearInterval(timer);timer=null;}const when=new Date().toLocaleString('zh-TW');winners.forEach(w=>drawn.push({round,type:w.type,name:w.name,time:when}));const main=winners.filter(w=>w.type==='正取'),alt=winners.filter(w=>w.type==='候補');$('#rfOut').innerHTML=`<div class="raffle-result"><div class="raffle-confetti">🎉 ✨ 🎊</div>${main.length?`<div class="raffle-label">正取</div><div class="raffle-winners">${main.map(w=>esc(w.name)).join('<span class="raffle-sep">、</span>')}</div>`:''}${alt.length?`<div class="raffle-label alternate">候補</div><div class="raffle-winners alternate">${alt.map(w=>esc(w.name)).join('<span class="raffle-sep">、</span>')}</div>`:''}<div class="raffle-round">第 ${round} 輪</div></div>`;$('#rfHistory').innerHTML=`<div class="hint">尚未抽出 ${pool.length} 筆名單</div>${htmlTable([['輪次','類型','姓名','時間'],...drawn.map(x=>[x.round,x.type,x.name,x.time])])}`;$('#rfCsv').disabled=false;$('#rfMeta').innerHTML=`<div class="metric-grid"><div class="metric"><b>${drawn.filter(x=>x.type==='正取').length}</b><span>累計正取</span></div><div class="metric"><b>${drawn.filter(x=>x.type==='候補').length}</b><span>累計候補</span></div><div class="metric"><b>${pool.length}</b><span>剩餘</span></div></div>`;setBusy(false);}
 $('#rfReset').onclick=reset;$('#rfDedupe').onchange=()=>{pool=[];drawn=[];source='';$('#rfMeta').innerHTML='<div class="warn-box">重複資料設定已變更，下一次抽籤會重新建立本輪名單。</div>';};$('#rfIn').oninput=()=>{if($('#rfIn').value!==source){pool=[];drawn=[];$('#rfMeta').innerHTML='<div class="warn-box">名單已變更，下一次抽籤會自動建立新一輪。</div>';}};
 $('#rfRun').onclick=()=>{if(busy)return;if(!pool.length&&!drawn.length&&!reset())return;if(!pool.length)return toast('本輪名單已全部抽完');const requestedMain=clamp(+$('#rfCount').value||0,0,100),requestedAlt=clamp(+$('#rfAltCount').value||0,0,100);if(requestedMain+requestedAlt<1)return toast('正取或候補至少要有 1 人');const total=Math.min(pool.length,requestedMain+requestedAlt),mainCount=Math.min(requestedMain,total),altCount=total-mainCount,candidates=[...pool],drawOrder=shuffle(pool),selectedNames=drawOrder.slice(0,total),winners=selectedNames.map((name,i)=>({name,type:i<mainCount?'正取':'候補'})),round=drawn.length?Math.max(...drawn.map(x=>x.round))+1:1,duration=clamp(+$('#rfAnimation').value||0,0,3000),myToken=++token;pool=drawOrder.slice(total);setBusy(true);if(!duration){finish(winners,round,myToken);return;}let elapsed=0,step=70;$('#rfOut').innerHTML='<div class="raffle-spinning">抽籤中…</div><div class="raffle-preview" id="rfPreview"></div>';const preview=$('#rfPreview');timer=setInterval(()=>{if(myToken!==token){clearInterval(timer);timer=null;return;}elapsed+=step;const show=[];for(let i=0;i<total;i++)show.push(candidates[secureRandomInt(candidates.length)]);preview.textContent=show.join('　');preview.classList.toggle('pulse');if(elapsed>=duration){clearInterval(timer);timer=null;setTimeout(()=>finish(winners,round,myToken),120);}},step);};
 $('#rfFullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#rfOut').requestFullscreen();}catch{toast('目前瀏覽器未允許全螢幕');}};
 $('#rfCsv').onclick=()=>drawn.length&&downloadCsvRows([['輪次','類型','姓名','抽籤時間'],...drawn.map(x=>[x.round,x.type,x.name,x.time])],'抽籤紀錄.csv');setToolCleanup(()=>{token++;if(timer)clearInterval(timer);timer=null;if(document.fullscreenElement===$('#rfOut'))document.exitFullscreen().catch(()=>{});});
});

addTool('seat-plan','list','🪑','座位表產生器','可隨機排列、設定每列座位數，並輸出座位 CSV。','座位表 seat 名單 隨機 csv 講台',()=>{
 mount.innerHTML=panel('座位表',`${textAreaField('spIn','名單（一行一人）')}<div class="row">${inputField('spCols','每列座位數','number','5','min="1" max="20"')}<label><input id="spShuffle" type="checkbox" checked> 隨機排列</label><label><input id="spFront" type="checkbox" checked> 顯示講台方向</label></div><div class="actions"><button class="primary-btn" id="spRun">產生座位表</button><button class="ghost-btn" id="spCsv" disabled>下載 CSV</button></div><div id="spOut"></div>`);let seats=[];$('#spRun').onclick=()=>{const src=$('#spIn').value;if(!validateTextSize(src,1_000_000,'名單'))return;let names=parseLines(src);if(names.length>20000)return toast('名單過多，上限 20,000 人');if(!names.length)return toast('請輸入名單');const duplicateNames=names.length-unique(names).length;if($('#spShuffle').checked)names=shuffle(names);const cols=clamp(+$('#spCols').value||5,1,20);seats=names.map((x,i)=>({no:i+1,row:Math.floor(i/cols)+1,col:i%cols+1,name:x}));$('#spCsv').disabled=false;$('#spOut').innerHTML=`${duplicateNames?`<div class="warn-box">偵測到 ${duplicateNames} 筆完全相同姓名，座位表會保留每一筆，不會自動刪除。</div>`:''}${$('#spFront').checked?'<div class="success-box text-center">⬆ 講台／前方 ⬆</div>':''}<div class="seat-grid seat-grid-dynamic cols-${cols}" data-cols="${cols}">${seats.map(x=>`<div class="seat"><small>${x.no}｜第${x.row}列-${x.col}</small><br><b>${esc(x.name)}</b></div>`).join('')}</div>`;};$('#spCsv').onclick=()=>seats.length&&downloadCsvRows([['座號','列','欄','姓名'],...seats.map(x=>[x.no,x.row,x.col,x.name])],'座位表.csv');
});

addTool('workday','date','🗓️','工作天計算器','計算工作天並拆解六日、自訂休假，也可選擇是否包含起訖日。','工作天 日期 假日 deadline 起訖日',()=>{
 mount.innerHTML=panel('工作天計算',`<div class="row">${inputField('wdStart','開始日期','date',ymd(new Date()))}${inputField('wdEnd','結束日期','date',ymd(new Date(Date.now()+7*864e5)))}</div>${textAreaField('wdHolidays','額外排除日期（選填，一行一筆）','2026-10-10')}<div class="row"><label><input id="wdIncludeStart" type="checkbox" checked> 包含開始日</label><label><input id="wdIncludeEnd" type="checkbox" checked> 包含結束日</label></div><div class="actions"><button class="primary-btn" id="wdRun">計算</button></div><div id="wdOut"></div>`);$('#wdRun').onclick=()=>{let a=parseDateLoose($('#wdStart').value),b=parseDateLoose($('#wdEnd').value);if(!a||!b)return toast('日期不正確');if(a>b)[a,b]=[b,a];const hol=new Set(parseLines($('#wdHolidays').value).map(parseDateLoose).filter(Boolean).map(ymd));let work=0,total=0,weekend=0,holiday=0;for(let d=new Date(a);d<=b;d.setDate(d.getDate()+1)){if(ymd(d)===ymd(a)&&!$('#wdIncludeStart').checked)continue;if(ymd(d)===ymd(b)&&!$('#wdIncludeEnd').checked)continue;total++;const key=ymd(d);if(d.getDay()===0||d.getDay()===6){weekend++;continue;}if(hol.has(key)){holiday++;continue;}work++;}$('#wdOut').innerHTML=`<div class="metric-grid"><div class="metric"><b>${work}</b><span>工作天</span></div><div class="metric"><b>${total}</b><span>計入日曆天</span></div><div class="metric"><b>${weekend}</b><span>六日</span></div><div class="metric"><b>${holiday}</b><span>自訂休假</span></div></div>`;};
},true);

addTool('work-hours','date','🧮','工時時間計算器','支援跨日、休息時間與標準工時，可估算超出標準的時間。','工時 上班 下班 午休 加班 標準工時',()=>{
 mount.innerHTML=panel('工時計算',`<div class="row">${inputField('whStart','上班','time','08:00')}${inputField('whEnd','下班','time','17:30')}${inputField('whBreak','休息分鐘','number','60','min="0" max="1440"')}${inputField('whStandard','標準工時（小時）','number','8','min="0" max="24" step="0.25"')}</div><div class="actions"><button class="primary-btn" id="whRun">計算</button></div><div id="whOut"></div>`);$('#whRun').onclick=()=>{if(!$('#whStart').value||!$('#whEnd').value)return toast('請輸入完整上下班時間');const[sh,sm]=$('#whStart').value.split(':').map(Number),[eh,em]=$('#whEnd').value.split(':').map(Number),br=clamp(+$('#whBreak').value||0,0,1440),std=clamp(+$('#whStandard').value||0,0,24)*60;let span=eh*60+em-(sh*60+sm);if(span<0)span+=1440;if(br>span)return toast('休息時間不可大於總時段');const mins=span-br,extra=Math.max(0,mins-std);$('#whOut').innerHTML=`<div class="metric-grid"><div class="metric"><b>${Math.floor(span/60)} 小時 ${span%60} 分</b><span>在場時段</span></div><div class="metric"><b>${Math.floor(mins/60)} 小時 ${mins%60} 分</b><span>實際工時</span></div><div class="metric"><b>${(mins/60).toFixed(2)}</b><span>十進位小時</span></div><div class="metric"><b>${Math.floor(extra/60)} 小時 ${Math.round(extra%60)} 分</b><span>超出標準工時</span></div></div><div class="hint">「超出標準工時」僅為時間差試算，不代表法定加班費或加班認定。</div>`;};
},true);

addTool('deadline','date','⏳','期限日期計算器','從指定日期加減日曆天／工作天，可排除休假並選擇是否把基準日算第 1 天。','期限 deadline 加天 工作日 假日 基準日',()=>{
 mount.innerHTML=panel('期限計算',`<div class="row">${inputField('dlDate','基準日期','date',ymd(new Date()))}${inputField('dlDays','天數','number','7','min="-36500" max="36500"')}<div class="field"><label>計算方式</label><select id="dlMode"><option value="calendar">日曆天</option><option value="work">工作天（排除六日＋自訂休假）</option></select></div></div>${textAreaField('dlHolidays','額外排除日期（工作天模式選填，一行一筆）','2026-10-10')}<div class="row"><label><input id="dlIncludeBase" type="checkbox"> 基準日符合條件時算第 1 天</label></div><div class="hint">最多前後 36,500 天。負數代表往前計算；工作天模式會排除六、日及有效自訂休假。</div><div class="actions"><button class="primary-btn" id="dlRun">計算期限</button></div><div id="dlOut"></div>`);$('#dlRun').onclick=()=>{const d=parseDateLoose($('#dlDate').value),n=Number($('#dlDays').value);if(!d)return toast('基準日期不正確');if(!Number.isInteger(n)||Math.abs(n)>36500)return toast('天數需為 -36500～36500 的整數');const holidayLines=parseLines($('#dlHolidays').value),parsed=holidayLines.map(parseDateLoose),hol=new Set(parsed.filter(Boolean).map(ymd)),invalid=parsed.filter(x=>!x).length,step=n>=0?1:-1;let left=Math.abs(n),countedBase=false;const eligible=x=>$('#dlMode').value==='calendar'||(x.getDay()!==0&&x.getDay()!==6&&!hol.has(ymd(x)));if(left&&$('#dlIncludeBase').checked&&eligible(d)){left--;countedBase=true;}while(left){d.setDate(d.getDate()+step);if(eligible(d))left--;}$('#dlOut').innerHTML=`<div class="success-box emphasis-result">📅 ${ymd(d)}　星期${weekdayZh(d)}　／　${toROCDate(d)}</div><div class="hint">${countedBase?'基準日已計為第 1 天。':'基準日未計入天數。'}${invalid?` 有 ${invalid} 筆自訂休假日期無法辨識，已忽略。`:''}</div>`;};
});

// ===== 應用程式導覽與搜尋 =====
function renderNav(){ $('#categoryNav').innerHTML=categories.map(([id,ic,n])=>`<button class="nav-btn ${id==='all'?'active':''}" data-cat="${id}">${ic} ${n}<span class="nav-count">${id==='all'?tools.length:tools.filter(t=>t.cat===id).length}</span></button>`).join('');$$('[data-cat]').forEach(b=>b.onclick=()=>{const next=b.dataset.cat;if(!showHome())return;state.category=next;$$('[data-cat]').forEach(x=>x.classList.toggle('active',x.dataset.cat===state.category));renderCards();$('#sidebar').classList.remove('open');}); }
function card(t){return `<article class="tool-card" tabindex="0" data-tool="${t.id}"><div class="tool-icon">${t.icon}</div><h3>${esc(t.title)}</h3><p>${esc(t.desc)}</p><small>${categories.find(c=>c[0]===t.cat)?.[2]||''}</small></article>`;}
function renderCards(){const q=$('#toolSearch').value.trim().toLowerCase();let arr=tools.filter(t=>state.category==='all'||t.cat===state.category);if(q)arr=arr.filter(t=>(t.title+' '+t.desc+' '+t.keywords).toLowerCase().includes(q));const favoriteSection=$('#favoriteSection');if(favoriteSection)favoriteSection.classList.toggle('hidden',state.category!=='all'||!!q);$('#allToolGrid').innerHTML=arr.length?arr.map(card).join(''):'<div class="empty">找不到符合的工具。可以換個關鍵字，例如「Excel」、「圖片」、「名單」。</div>';$('#filterStatus').textContent=q?`找到 ${arr.length} 個工具`:(state.category==='all'?'依分類瀏覽':`只顯示「${categories.find(c=>c[0]===state.category)?.[2]||''}」工具`);bindCards();}
function bindCards(){ $$('[data-tool]').forEach(el=>{const go=()=>openTool(el.dataset.tool);el.onclick=go;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')go();};}); }
function showHome(){if(state.currentTool!==null&&!cleanupCurrentTool())return false;state.currentTool=null;$('#homeView').classList.add('active');$('#toolView').classList.remove('active');window.scrollTo({top:0});return true;}
function openTool(id){const t=tools.find(x=>x.id===id);if(!t)return false;if(state.currentTool!==null&&!cleanupCurrentTool())return false;state.currentTool=id;$('#homeView').classList.remove('active');$('#toolView').classList.add('active');$('#toolCategory').textContent=`${categories.find(c=>c[0]===t.cat)?.[1]||''} ${categories.find(c=>c[0]===t.cat)?.[2]||''}`;$('#toolTitle').textContent=t.title;$('#toolDesc').textContent=t.desc;mount.innerHTML='';try{t.render();}catch(e){console.error(e);mount.innerHTML=`<div class="error-box"><b>工具執行時發生錯誤</b><br>${esc(e.message)}</div>`;}window.scrollTo({top:0});$('#sidebar').classList.remove('open');}
$('#toolSearch').addEventListener('input',()=>{if(showHome())renderCards();});$('#homeBtn').onclick=showHome;$('#backBtn').onclick=showHome;$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');
$('#toolCount').textContent=tools.length;renderNav();$('#favoriteGrid').innerHTML=tools.filter(t=>t.favorite).map(card).join('');renderCards();bindCards();
if(typeof window.XLSX==='undefined')$('#buildNotice')?.classList.remove('hidden');
$('#exportConfirm').onclick=()=>{if(!exportState.blob)return;const blob=exportState.blob,name=exportState.name;closeExportPreview();directDownload(blob,name);};
$('#exportCancel').onclick=closeExportPreview;$('#exportClose').onclick=closeExportPreview;$('#exportBackdrop').onclick=closeExportPreview;
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#exportModal')?.classList.contains('hidden'))closeExportPreview();});
